static int checks=0;static void check(bool ok,const char* s){if(!ok)throw std::runtime_error(s);++checks;std::cout<<"PASS "<<s<<std::endl;}
static void pump(int ms){auto until=monotonic()+ms*.001;while(monotonic()<until){MSG m;while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Thread::sleep(1);}}
static void wait(std::function<bool()> f,const char* s){auto until=monotonic()+3;while(!f()&&monotonic()<until)pump(10);check(f(),s);}
static void lightMapping(Mapping& mapping,Parameter* sensor,Parameter* light){mapping.setForceDisabled(true,true);auto* input=new StandardMappingInput();mapping.im.addItem(input);input->inputTarget->setValueFromTarget(sensor);auto* output=mapping.om.addItem();auto* engine=dynamic_cast<ChataigneEngine*>(Engine::mainEngine);output->setCommand(engine->module->getCommandDefinitionFor("","Set Parameter Value"));auto* command=dynamic_cast<GenericControllableCommand*>(output->command.get());command->target->setValueFromTarget(light);mapping.updateMappingChain(nullptr,false);}
