 auto old=run->mapping;auto* delayed=old->instance->om.items[0];auto captured=[delayed]{delayed->setValue(var(Array<var>{.9}),0);};auto dispatchCount=old->gate->dispatched;c.end(runId);captured();sensor->setValue(.95);pump(50);check(std::abs(light->doubleValue()-.7)<1e-5&&old->gate->dispatched==dispatchCount,"B1/B3 End closes final admission and leaves last light value");
 // Force the ordinary disabled flag open only in this fixture: final generation gate still rejects.
 delayed->forceDisabled=false;captured();check(old->gate->rejected>0&&std::abs(light->doubleValue()-.7)<1e-5,"B3 already-captured request rejected at final gate after End");auto restarted=c.direct(cue->id,true);auto fresh=c.runs[restarted]->mapping;check(fresh!=old&&fresh->generation!=old->generation,"B4 Restart creates independent instance and generation");captured();check(fresh->gate->dispatched==1&&std::abs(light->doubleValue()-.95)<1e-5,"B3 old request after Restart cannot reach new run");c.end(restarted);
 auto* state=new State();StateManager::getInstance()->addItem(state);auto* source=new Mapping();state->pm->addItem(source);lightMapping(*source,sensor,otherLight);state->active->setValue(true);source->setForceDisabled(false,true);source->process(true,-1,true);bool enabled=source->enabled->boolValue();auto linked=c.add(CueType::Mapping);linked->sourceMapping->setValue(source->showDefinitionId);auto linkedId=c.direct(linked->id);auto instance=c.runs[linkedId]->mapping;check(instance&&instance->instance.get()!=source&&source->enabled->boolValue()==enabled,"B2 linked Mapping is a snapshot clone; original enable state untouched");auto definition=JSON::toString(instance->instance->getJSONData());source->sendOnInputChangeOnly->setValue(!source->sendOnInputChangeOnly->boolValue());check(JSON::toString(instance->instance->getJSONData())==definition,"B2 original edits do not mutate an active private instance");c.end(linkedId);sensor->setValue(.31);wait([&]{return std::abs(otherLight->doubleValue()-.31)<1e-5;},"B2 original Mapping continues after exact clone End");check(source->enabled->boolValue()==enabled,"B2 ending clone does not toggle original enabled state");source->setForceDisabled(true,true);

 auto separate=c.add(CueType::Mapping);separate->sourceMapping->setValue(source->showDefinitionId);auto linkedA=c.direct(linked->id,true),linkedB=c.direct(separate->id);check(c.runs[linkedA]->mapping!=c.runs[linkedB]->mapping,"B2 two cues independently instantiate the same source definition");c.end(linkedA);check(c.runs[linkedB]->mapping->processing,"B2 ending one shared-source clone preserves the other");c.end(linkedB);
